  "src/app/renderer/services/window.ts": "import type { FluxBridge } from \"fluxplugin\";\nimport { CHANNELS } from \"../../shared/constants\";\n\n/** Colours the native window buttons (Windows/Linux). A no-op error in browser mode is ignored on purpose. */\nexport function setTitleBarOverlay(bridge: FluxBridge, color: string, symbolColor: string): void {\n  void bridge.invoke(CHANNELS.setTitleBarOverlay, { color, symbolColor }).catch(() => undefined);\n}\n",
  "src/app/renderer/shell/AppShell.tsx": "import { Breadcrumbs, CommandPalette, PluginRoutes, PluginSlot, TitleBar, useKeybindings } from \"fluxplugin/react\";\nimport { APP_NAME, SLOTS } from \"../../shared/constants\";\nimport { Sidebar } from \"./Sidebar\";\n\n/** Whole window: custom title bar (menus, search, theme, notifications) → sidebar + routed content. */\nexport function AppShell() {\n  useKeybindings(); // runs commands bound to keyboard shortcuts (Mod+Shift+R, ...)\n  return (\n    <div className=\"app\">\n      <TitleBar title={APP_NAME} logo={<PluginSlot name={SLOTS.brandBadges} />} searchPlaceholder=\"Search commands, pages…\" />\n      <div className=\"body\">\n        <Sidebar />\n        <main className=\"main\">\n          <Breadcrumbs />\n          <PluginRoutes />\n        </main>\n      </div>\n      <CommandPalette />\n    </div>\n  );\n}\n",
  "src/app/renderer/shell/Sidebar.tsx": "import { Link, useMenu } from \"fluxplugin/react\";\n\nexport function Sidebar() {\n  const { items, run } = useMenu(\"sidebar\"); // entries added by plugins (routes with meta.menu, or menus.register)\n  return (\n    <aside className=\"side\">\n      <Link to=\"/\">Dashboard</Link>\n      {items.map((i) => (\n        <a key={i.id} href={\"#\" + i.path} onClick={(e) => (e.preventDefault(), run(i))}>\n          {i.label}\n        </a>\n      ))}\n      <Link to=\"/plugins\">Plugins</Link>\n      <p className=\"hint\">Ctrl/Cmd+K: commands</p>\n    </aside>\n  );\n}\n",
  "src/app/renderer/styles/app.css": "body { margin: 0; font: 14px system-ui; background: var(--flux-bg); color: var(--flux-fg); }\n.app { display: grid; grid-template-rows: var(--flux-titlebar-h, 40px) 1fr; min-height: 100vh; }\n.body { display: grid; grid-template-columns: 220px 1fr; min-height: 0; }\n.side { border-right: 1px solid var(--flux-border); padding: 16px; background: var(--flux-surface); }\n.side a { display: block; padding: 7px 10px; border-radius: 8px; color: inherit; text-decoration: none; margin: 2px 0; }\n.side a[data-active] { background: var(--flux-accent); color: #fff; }\n.main { padding: 24px; max-width: 860px; overflow: auto; }\n.row { display: flex; gap: 8px; margin: 12px 0; flex-wrap: wrap; }\n.btn { border: 1px solid var(--flux-border); background: var(--flux-bg); color: inherit; border-radius: 8px; padding: 6px 12px; cursor: pointer; }\n.hint { color: var(--flux-muted); font-size: 12px; }\n",
  "src/app/shared/constants.ts": "/** Names shared by the main process and the renderer. No imports here: this layer depends on nothing. */\nexport const APP_NAME = \"__APP_NAME__\";\n\n/** Height of the custom title bar in px (must match --flux-titlebar-h in CSS). */\nexport const TITLEBAR_HEIGHT = 40;\n\n/** IPC channels the host exposes to the renderer (also allow-listed in main/framework.ts). */\nexport const CHANNELS = {\n  createItem: \"host.item.create\",\n  /** Colours the native window buttons (Windows/Linux overlay) to match the current theme. */\n  setTitleBarOverlay: \"host.window.setTitleBarOverlay\",\n} as const;\n\n/** Declarative extension points the host offers to plugins (see renderer/extension-points.ts).\n *  The built-in \"theme\" and \"titlebar\" points are declared by declareHostPoints(). */\nexport const EXTENSION_POINTS = {\n  dashboard: \"dashboard\",\n} as const;\n\n/** UI slots where plugins can inject components (see <PluginSlot name=... />). */\nexport const SLOTS = {\n  brandBadges: \"header.badges\",\n  titlebarLeft: \"titlebar.left\",\n  titlebarRight: \"titlebar.right\",\n  dashboardBefore: \"dashboard.before\",\n  dashboardAfter: \"dashboard.after\",\n} as const;\n\n/** Hook pipeline operations plugins can intercept: before./after./transform./validate.<operation>. */\nexport const OPERATIONS = {\n  createItem: \"item.create\",\n} as const;\n",
